import{_ as a,o as r,c as e,a3 as o}from"./chunks/framework.DMtjdCb-.js";const n="/help/assets/hidden-works.ja.Bp0QsUGQ.png",s="/help/assets/library-settings.ja.CkQdugF4.png",d="/help/assets/history.ja.Cv1noD_S.png",b=JSON.parse('{"title":"8. 日常の管理","description":"","frontmatter":{},"headers":[],"relativePath":"ja/manage.md","filePath":"ja/manage.md"}'),i={name:"ja/manage.md"};function l(h,t,p,c,g,_){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="_8-日常の管理" tabindex="-1">8. 日常の管理 <a class="header-anchor" href="#_8-日常の管理" aria-label="Permalink to &quot;8. 日常の管理&quot;">​</a></h1><h2 id="検索・絞り込み・非表示" tabindex="-1">検索・絞り込み・非表示 <a class="header-anchor" href="#検索・絞り込み・非表示" aria-label="Permalink to &quot;検索・絞り込み・非表示&quot;">​</a></h2><p>ホームはカードと表を切り替え、年代、種類、リソース元、保存状態で絞り込めます。<strong>すべてリセット</strong> で既定に戻ります。タイトル検索では、既定の絞り込み対象外や非表示の作品も見つけられます。</p><p>レーダーや詳細で <strong>非表示</strong> にすると通常の一覧から外れます。購読、ダウンロード、視聴記録は保持されます。</p><p>戻す場合は <strong>新作レーダー → 非表示の作品</strong> で探し、<strong>再表示</strong> します。</p><p><img src="'+n+'" alt="非表示の作品：検索して一覧に戻す" loading="lazy"></p><h2 id="購読の一時停止・解除・削除" tabindex="-1">購読の一時停止・解除・削除 <a class="header-anchor" href="#購読の一時停止・解除・削除" aria-label="Permalink to &quot;購読の一時停止・解除・削除&quot;">​</a></h2><p>レーダーの購読状態メニュー、または作品詳細から選びます。</p><table tabindex="0"><thead><tr><th>操作</th><th>以降の取得</th><th>保存済みファイル</th></tr></thead><tbody><tr><td>購読を一時停止</td><td>一時停止し、再開可能</td><td>保持</td></tr><tr><td>ファイルを保持して購読解除</td><td>購読終了</td><td>保持</td></tr><tr><td>購読とファイルを削除</td><td>購読削除</td><td>確認画面の対象を削除</td></tr><tr><td>作品を非表示</td><td>元の購読を継続</td><td>保持</td></tr></tbody></table><p>ファイル削除では、確認画面の作品名と対象範囲を確認して実行します。</p><h2 id="購読用フォルダーを作る" tabindex="-1">購読用フォルダーを作る <a class="header-anchor" href="#購読用フォルダーを作る" aria-label="Permalink to &quot;購読用フォルダーを作る&quot;">​</a></h2><p>ローカルライブラリが接続済みで書き込み可能な場合、レーダーの <strong>フォルダー</strong> から購読作品の空フォルダーを作成できます。既存フォルダーは再利用し、結果は履歴で確認できます。</p><h2 id="ライブラリの休止時間を設定する" tabindex="-1">ライブラリの休止時間を設定する <a class="header-anchor" href="#ライブラリの休止時間を設定する" aria-label="Permalink to &quot;ライブラリの休止時間を設定する&quot;">​</a></h2><ol><li><strong>設定 → 接続 → ローカルライブラリ</strong> を開きます。</li><li>毎日の休止時間を有効にし、開始・終了時刻を指定します。</li><li>画面の実行機器の時刻を確認して保存します。</li></ol><p><img src="'+s+'" alt="休止時間：実行機器の時刻を確認して設定" loading="lazy"></p><p>AnimeMachine の実行機器の時刻を使用し、日付をまたぐ設定も可能です。休止中はローカルライブラリへのアクセスを止め、既知の状態を保持します。Ani-RSS や他の再生元は独立して利用できます。</p><p>この設定が制御するのは AnimeMachine のアクセスです。同じディスクを他のアプリが使用する場合、実際のディスク休止は NAS や各サービスの動作にも依存します。</p><h2 id="履歴とログを読む" tabindex="-1">履歴とログを読む <a class="header-anchor" href="#履歴とログを読む" aria-label="Permalink to &quot;履歴とログを読む&quot;">​</a></h2><p><strong>設定 → 履歴</strong> は整理・フォルダー・ダウンロードの操作結果、<strong>設定 → ログ</strong> は動作中のメッセージを表示します。警告・エラーに絞ってから、作品名やキーワードで検索できます。</p><p><img src="'+d+'" alt="履歴：操作と作品から結果を確認" loading="lazy"></p>',20)])])}const u=a(i,[["render",l]]);export{b as __pageData,u as default};
